const PRACTICALS_SUBJECTS = ['Biology', 'Chemistry', 'Physics', 'Laboratory Science', 'P7 Visit'];
const SUBJECT_LEVELS = {
    'Biology': ['S1', 'S2', 'N4', 'N4/N5', 'Higher', 'Higher Human', 'Advanced Higher'],
    'Chemistry': ['S1', 'S2', 'N4/N5', 'Higher', 'Advanced Higher'],
    'Physics': ['S1', 'S2', 'N4/N5', 'Higher', 'Advanced Higher'],
    'Laboratory Science': ['N4/N5'],
    'P7 Visit': []
};
const TOPIC_LEVELS = ['S1', 'S2', 'Higher', 'Higher Human', 'Advanced Higher'];

function naturalSortKey(title) {
    const markerMatch = title.match(/(?:L(?:esson)?\.?\s*0*(\d+)(?:\.(\d+))?)|(?:Activity\s*0*(\d+))|(?:Exp(?:eriment)?\.?\s*0*(\d+))/i);
    if (markerMatch) {
        const major = parseInt(markerMatch[1] || markerMatch[3] || markerMatch[4], 10);
        const minor = markerMatch[2] ? parseInt(markerMatch[2], 10) : 0;
        return [major, minor];
    }
    const decMatch = title.match(/\b(\d+)\.(\d+)\b/);
    if (decMatch) {
        return [parseInt(decMatch[1], 10), parseInt(decMatch[2], 10)];
    }
    const anyNum = title.match(/\d+/);
    if (anyNum) return [parseInt(anyNum[0], 10)];
    return null;
}

function compareSortKeys(ka, kb) {
    if (ka === null && kb === null) return 0;
    if (ka === null) return 1;
    if (kb === null) return -1;
    const len = Math.max(ka.length, kb.length);
    for (let i = 0; i < len; i++) {
        const va = ka[i] !== undefined ? ka[i] : 0;
        const vb = kb[i] !== undefined ? kb[i] : 0;
        if (va !== vb) return va - vb;
    }
    return 0;
}

function sortPracticals(list) {
    return list.slice().sort((a, b) => {
        if (a.isRevision !== b.isRevision) return a.isRevision ? 1 : -1;
        const cmp = compareSortKeys(naturalSortKey(a.title), naturalSortKey(b.title));
        if (cmp !== 0) return cmp;
        return a.title.localeCompare(b.title);
    });
}

function showPracticalsHome() {
    pushState({ type: 'practicals-home' });
    let html = '<h3>Subject</h3><div class="cabinet-buttons">';
    PRACTICALS_SUBJECTS.forEach(subject => {
        const count = allPracticals.filter(t => t.subject === subject).length;
        html += `<button class="subarea-button-js" data-parent="Practicals" data-subarea="${subject}">${subject} (${count})</button>`;
    });
    html += '</div>';
    showContent('Practicals', html);
    attachDynamicEventListeners();
}

function showPracticalsSubject(subject) {
    pushState({ type: 'practicals-subject', subject: subject });
    const levels = SUBJECT_LEVELS[subject] || [];
    if (levels.length === 0) {
        showPracticalsLevel(subject, null);
        return;
    }
    let html = `<h3>${subject} - Level</h3><div class="cabinet-buttons">`;
    levels.forEach(level => {
        const count = allPracticals.filter(t => t.subject === subject && t.level === level).length;
        if (count > 0) {
            html += `<button class="shelf-button-js" data-parent="Practicals" data-subarea="${subject}" data-shelf="${level}">${level} (${count})</button>`;
        }
    });
    html += '</div>';
    showContent(`Practicals - ${subject}`, html);
    attachDynamicEventListeners();
}

function showPracticalsLevel(subject, level) {
    pushState({ type: 'practicals-level', subject: subject, level: level });
    const matches = allPracticals.filter(t => t.subject === subject && t.level === level);
    const hasTopics = (level && TOPIC_LEVELS.includes(level)) || matches.some(t => t.topic);
    if (hasTopics) {
        const topics = [...new Set(matches.map(t => t.topic || 'General'))].sort();
        let html = `<h3>${level || subject} - Topic</h3><div class="cabinet-buttons">`;
        topics.forEach(topic => {
            const count = matches.filter(t => (t.topic || 'General') === topic).length;
            html += `<button class="nested-shelf-button-js" data-parent="${subject}" data-subarea="${level || ''}" data-nestedshelf="${topic}">${topic} (${count})</button>`;
        });
        html += '</div>';
        showContent(`Practicals - ${subject}` + (level ? ` - ${level}` : ''), html);
        attachDynamicEventListeners();
    } else {
        renderPracticalsListHTML(subject, level, null, matches);
    }
}

function showPracticalsTopic(subject, level, topic) {
    pushState({ type: 'practicals-topic', subject: subject, level: level, topic: topic });
    const matches = allPracticals.filter(t => t.subject === subject && t.level === level && (t.topic || 'General') === topic);
    renderPracticalsListHTML(subject, level, topic, matches);
}

function renderPracticalsListHTML(subject, level, topic, matches) {
    matches = sortPracticals(matches);
    let title = `Practicals - ${subject}` + (level ? ` - ${level}` : '') + (topic ? ` - ${topic}` : '');
    let html = '<ul>';
    if (matches.length === 0) {
        html += '<p>No practicals found here.</p>';
    } else {
        matches.forEach(t => {
            html += `
                <li class="equipment-item practical-list-item" data-action="open-practical" data-id="${t.id}">
                    <span class="equipment-name">${t.title}</span>
                    ${t.isRevision ? '<span class="practical-tag practical-tag-revision">Revision / Test</span>' : ''}
                </li>
            `;
        });
    }
    html += '</ul>';
    showContent(title, html);
    attachDynamicEventListeners();
}

function showPracticalsDetail(id) {
    pushState({ type: 'practicals-detail', id: id });
    const t = allPracticals.find(p => p.id === id);
    if (!t) {
        showContent('Practical not found', '<p>This practical could not be found.</p>');
        return;
    }
    let html = '<div class="practical-tags">';
    if (t.subject) html += `<span class="practical-tag">${t.subject}</span>`;
    if (t.level) html += `<span class="practical-tag">${t.level}</span>`;
    if (t.topic) html += `<span class="practical-tag">${t.topic}</span>`;
    if (t.exam) html += `<span class="practical-tag practical-tag-exam">Exam</span>`;
    html += '</div>';

    html += '<h3>Equipment</h3><ul>';
    if (t.items.length === 0) {
        html += '<p>No equipment listed for this practical.</p>';
    } else {
        t.items.forEach(item => {
            html += '<li class="equipment-item">';
            html += `<span class="equipment-name">${item.name.replace(/\n/g, '<br>')}</span>`;
            if (item.qty) html += `<span class="practical-qty">${item.qty}</span>`;
            if (item.location) {
                html += `<button class="practical-location-btn" data-nav='${JSON.stringify(item.location.nav)}'><i class="fa-solid fa-location-dot"></i> ${item.location.label}</button>`;
            }
            html += '</li>';
        });
    }
    html += '</ul>';

    if (t.generalNotes) html += `<h3>General Notes</h3><p>${t.generalNotes.replace(/\n/g, '<br>')}</p>`;
    if (t.technicianNotes) html += `<h3>Technician Notes</h3><p>${t.technicianNotes.replace(/\n/g, '<br>')}</p>`;
    if (t.riskAssessmentNotes) html += `<h3>Risk Assessment Notes</h3><p>${t.riskAssessmentNotes.replace(/\n/g, '<br>')}</p>`;

    showContent(t.title, html);
    attachDynamicEventListeners();
}

function showPracticalsSearch(resultsHtml = '') {
    pushState({ type: 'practicals-search', resultsHtml: resultsHtml });
    let html = `
        <div class="search-container">
            <input type="text" id="practicalsSearchInput" placeholder="Search practicals...">
            <button id="practicalsSearchBtnConfirm">Search</button>
        </div>
        <div id="practicalsSearchResults">${resultsHtml}</div>
    `;
    showContent('Search Practicals', html);

    const searchInput = document.getElementById('practicalsSearchInput');
    const searchBtnConfirm = document.getElementById('practicalsSearchBtnConfirm');
    const searchResultsDiv = document.getElementById('practicalsSearchResults');
    searchInput.focus();

    const performSearch = () => {
        const query = searchInput.value.toLowerCase().trim();
        if (query.length < 2) {
            searchResultsDiv.innerHTML = '<p>Please enter at least 2 characters to search.</p>';
            return;
        }

        const matches = allPracticals.filter(t => {
            if (t.title.toLowerCase().includes(query)) return true;
            if (t.topic && t.topic.toLowerCase().includes(query)) return true;
            return t.items.some(item => item.name.toLowerCase().includes(query));
        }).sort((a, b) => a.title.localeCompare(b.title));

        let resultsHtml = '<h3>Search Results:</h3><ul>';
        if (matches.length === 0) {
            resultsHtml += '<li>No practicals found matching your search.</li>';
        } else {
            matches.forEach(t => {
                const subtitle = [t.subject, t.level, t.topic].filter(Boolean).join(' - ');
                resultsHtml += `
                    <li class="equipment-item practical-list-item" data-action="open-practical" data-id="${t.id}">
                        <span class="equipment-name">${t.title}</span>
                        <span class="practical-meta">${subtitle}</span>
                    </li>
                `;
            });
        }
        resultsHtml += '</ul>';
        searchResultsDiv.innerHTML = resultsHtml;

        const currentState = navigationStack[navigationStack.length - 1];
        if (currentState.type === 'practicals-search') {
            currentState.resultsHtml = resultsHtml;
        }
    };

    searchBtnConfirm.addEventListener('click', performSearch);
    searchInput.addEventListener('keypress', (e) => {
        if (e.key === 'Enter') {
            performSearch();
        }
    });
    attachDynamicEventListeners();
}

document.addEventListener('DOMContentLoaded', () => {
    backBtn.addEventListener('click', goBack);
    practicalsBtn.addEventListener('click', showPracticalsHome);
    practicalsSearchBtn.addEventListener('click', () => renderState({ type: 'practicals-search' }));
    searchBtn.addEventListener('click', () => renderState({ type: 'search' }));
    mapBtn.addEventListener('click', showMap);
    archiveBtn.addEventListener('click', showArchiveView);
    addEquipmentBtn.addEventListener('click', openAddEquipmentModal);
    closeAddEquipmentModal.addEventListener('click', () => addEquipmentModal.style.display = 'none');
    selectLocation.addEventListener('change', () => {
        const location = selectLocation.value;
        populateDynamicSelect(location);
        selectDynamic.value = '';
        dynamicContainer.classList.add('hidden');
        selectSubDynamic.innerHTML = '<option value="">Select an option</option>';
        subDynamicContainer.classList.add('hidden');
        if (location) dynamicContainer.classList.remove('hidden');
    });
    selectDynamic.addEventListener('change', () => {
        const location = selectLocation.value;
        const dynamicSelection = selectDynamic.value;
        populateSubDynamicSelect(location, dynamicSelection);
        subDynamicContainer.classList.add('hidden');
        if (location === 'Preproom' && ['Biology', 'Chemistry', 'Physics', 'Chemical Store'].includes(dynamicSelection)) {
            subDynamicContainer.classList.remove('hidden');
        }
    });
    addEquipmentForm.addEventListener('submit', (event) => {
        event.preventDefault();
        const location = selectLocation.value;
        const dynamicSelection = selectDynamic.value;
        const subDynamicSelection = selectSubDynamic.value;
        const name = equipmentNameInput.value.trim();
        let quantity = equipmentQuantityInput.value.trim();
        if (name && quantity) {
            if (!isNaN(quantity) && !isNaN(parseFloat(quantity))) {
                quantity = parseInt(quantity, 10);
            }
            addEquipment(location, dynamicSelection, subDynamicSelection, name, quantity);
            addEquipmentModal.style.display = 'none';
            addEquipmentForm.reset();
        } else {
            showCustomModal('Error', 'Please fill in all required fields.', 'error');
        }
    });
    signInBtn.addEventListener('click', async () => {
        const ok = await ensureSignedIn();
        if (ok) {
            signInBtn.classList.add('hidden');
            await loadFromSheet();
            startPolling();
        }
    });
    mapDiv.addEventListener('click', (event) => {
        const cell = event.target.closest('.map-cell');
        if (cell) {
            handleAreaSelection(cell.dataset.area);
        }
    });

    gateForm.addEventListener('submit', (event) => {
        event.preventDefault();
        const username = gateUsernameInput.value.trim();
        const password = gatePasswordInput.value;
        if (!username) {
            gateError.textContent = 'Please enter your name.';
            return;
        }
        if (password !== GATE_PASSWORD) {
            gateError.textContent = 'Incorrect password.';
            gatePasswordInput.value = '';
            gatePasswordInput.focus();
            return;
        }
        gateError.textContent = '';
        unlockApp(username);
    });

    switchUserBtn.addEventListener('click', () => {
        localStorage.removeItem(GATE_USER_KEY);
        localStorage.removeItem(GATE_AUTHED_KEY);
        location.reload();
    });

    themeMenuBtn.addEventListener('click', (event) => {
        event.stopPropagation();
        const isOpen = !themeMenu.classList.contains('hidden');
        themeMenu.classList.toggle('hidden');
        themeMenuBtn.setAttribute('aria-expanded', String(!isOpen));
    });

    document.querySelectorAll('.theme-option').forEach(btn => {
        btn.addEventListener('click', () => {
            applyTheme(btn.dataset.theme);
            themeMenu.classList.add('hidden');
            themeMenuBtn.setAttribute('aria-expanded', 'false');
        });
    });

    document.addEventListener('click', (event) => {
        if (!themeMenu.classList.contains('hidden') && !event.target.closest('.theme-menu-wrapper')) {
            themeMenu.classList.add('hidden');
            themeMenuBtn.setAttribute('aria-expanded', 'false');
        }
    });

    checkGate();
});

function openAddEquipmentModal() {
    addEquipmentModal.style.display = 'flex';
    populateLocationSelect();
    selectLocation.value = '';
    selectDynamic.innerHTML = '<option value="">Select an option</option>';
    dynamicContainer.classList.add('hidden');
    selectSubDynamic.innerHTML = '<option value="">Select an option</option>';
    subDynamicContainer.classList.add('hidden');
    equipmentNameInput.value = '';
    equipmentQuantityInput.value = '';
}

function populateLocationSelect() {
    selectLocation.innerHTML = '<option value="">Select a location</option>';
    const allLocations = Object.keys(equipmentData).sort();
    allLocations.forEach(location => {
        const option = document.createElement('option');
        option.value = location;
        option.textContent = location;
        selectLocation.appendChild(option);
    });
}

function populateDynamicSelect(location) {
    selectDynamic.innerHTML = '<option value="">Select an option</option>';
    dynamicLabel.textContent = 'Cabinet/Section:';
    const data = equipmentData[location];
    if (!data) return;

    if (location.startsWith('Lab')) {
        const labOptions = [];
        if (data.basic) {
            labOptions.push({ value: 'General Items', text: 'General Items (No specific cabinet)' });
        }
        if (data.cabinets) {
            Object.keys(data.cabinets).sort().forEach(cabinet => {
                labOptions.push({ value: cabinet, text: cabinet });
            });
        }

        labOptions.forEach(opt => {
            const option = document.createElement('option');
            option.value = opt.value;
            option.textContent = opt.text;
            selectDynamic.appendChild(option);
        });

    } else if (location === 'Preproom' && data.subcategories) {
        dynamicLabel.textContent = 'Section:';
        const sortedSubcategories = Object.keys(data.subcategories).sort();
        sortedSubcategories.forEach(subcatName => {
            const option = document.createElement('option');
            option.value = subcatName;
            option.textContent = subcatName;
            selectDynamic.appendChild(option);
        });
    } else if (['Greenhouse', 'Bookstore', 'Academy'].includes(location)) {
        dynamicLabel.textContent = 'Cabinet/Shelf:';
        if (data.basic && Array.isArray(data.basic)) {
            const option = document.createElement('option');
            option.value = 'General Items';
            option.textContent = 'General Items (No specific cabinet)';
            selectDynamic.appendChild(option);
        }
        if (data.cabinets) {
            Object.keys(data.cabinets).sort().forEach(cabinet => {
                const option = document.createElement('option');
                option.value = cabinet;
                option.textContent = cabinet;
                selectDynamic.appendChild(option);
            });
        }
    }
}

function populateSubDynamicSelect(location, dynamicSelection) {
    selectSubDynamic.innerHTML = '<option value="">Select an option</option>';
    subDynamicLabel.textContent = 'Column/Shelf:';
    if (location === 'Preproom') {
        const subcatData = equipmentData[location]?.subcategories?.[dynamicSelection];
        if (subcatData?.cabinets) {
            subDynamicLabel.textContent = 'Column:';
            Object.keys(subcatData.cabinets).sort().forEach(cabinetName => {
                const option = document.createElement('option');
                option.value = cabinetName;
                option.textContent = cabinetName;
                selectSubDynamic.appendChild(option);
            });
        } else if (dynamicSelection === 'Chemical Store' && subcatData) {
            subDynamicLabel.textContent = 'Shelf:';
            const chemicalStoreOptions = ['C1', 'C2', 'C3', 'C4'];
            chemicalStoreOptions.forEach(chemDivision => {
                const option = document.createElement('option');
                option.value = chemDivision;
                option.textContent = chemDivision;
                selectSubDynamic.appendChild(option);
            });
            if (subcatData.Shelves) {
                Object.keys(subcatData.Shelves).sort().forEach(shelfName => {
                    const option = document.createElement('option');
                    option.value = shelfName;
                    option.textContent = shelfName;
                    selectSubDynamic.appendChild(option);
                });
            }
        }
    }
}
